const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const delhi = ee.Geometry.Point([77.216721, 28.644800]);
    const delhiMetroArea = delhi.buffer(25000); // 25 km buffer for the metropolitan area
    const startDate = '2024-01-15';
    const endDate = '2024-01-16';

    // 2. Data Acquisition
    // Use Sentinel-2 Harmonized Surface Reflectance collection
    const s2_sr_collection = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
        .filterDate(startDate, endDate)
        .filterBounds(delhiMetroArea);

    // Use the corresponding cloud probability collection
    const s2_cloud_prob_collection = ee.ImageCollection('COPERNICUS/S2_CLOUD_PROBABILITY')
        .filterDate(startDate, endDate)
        .filterBounds(delhiMetroArea);

    // Check if collections are empty
    const imageCount = s2_sr_collection.size().getInfo();
    if (imageCount === 0) {
        console.log('No Sentinel-2 images found for the specified date and location.');
        console.log('A: No');
        return; // No images means no cloud coverage from this source.
    }
    console.log(`Found ${imageCount} image(s) for the analysis.`);

    // Merge collections and select the first image (should be only one for a single day)
    const s2_sr_image = ee.Image(s2_sr_collection.first());
    const s2_cloud_prob_image = ee.Image(s2_cloud_prob_collection.first());

    // 3. Processing
    // Define a threshold for cloud probability.
    const CLOUD_PROBABILITY_THRESHOLD = 65;
    // Create a binary cloud mask: 1 where cloud probability > threshold, 0 otherwise.
    const cloudMask = s2_cloud_prob_image.select('probability').gt(CLOUD_PROBABILITY_THRESHOLD);
    const imageWithMask = s2_sr_image.addBands(cloudMask.rename('cloud_mask'));

    // 4. Calculation
    // Use a reducer to count total pixels and cloudy pixels within the ROI.
    const reducers = ee.Reducer.count().group({
        groupField: 1,
        groupName: 'cloud_mask',
    });

    const stats = imageWithMask.select(['B2', 'cloud_mask']).reduceRegion({
        reducer: reducers,
        geometry: delhiMetroArea,
        scale: 1000,
        maxPixels: 1e9
    });

    const statsInfo = stats.getInfo()['groups'];

    if (!statsInfo || statsInfo.length === 0) {
        console.log('No valid pixels found within the geometry for calculation.');
        console.log('C2');
        return;
    }

    // 5. Validation & Final Answer
    let cloudyPixels = 0;
    let nonCloudyPixels = 0;

    statsInfo.forEach(group => {
        if (group['cloud_mask'] === 1) {
            cloudyPixels = group['count'];
        } else if (group['cloud_mask'] === 0) {
            nonCloudyPixels = group['count'];
        }
    });

    const totalPixels = cloudyPixels + nonCloudyPixels;
    if (totalPixels === 0) {
        console.log("Total pixel count in the ROI is zero.");
        console.log('C2');
        return;
    }

    const cloudCoveragePercentage = (cloudyPixels / totalPixels) * 100;

    console.log(`Analysis for Delhi on ${startDate}:`);
    console.log(`Total Pixels in ROI: ${totalPixels}`);
    console.log(`Cloudy Pixels (Prob > ${CLOUD_PROBABILITY_THRESHOLD}%): ${cloudyPixels}`);
    console.log(`Cloud Coverage: ${cloudCoveragePercentage.toFixed(2)}%`);

    // Check for "complete" coverage, allowing for a small tolerance (e.g., 99%).
    if (cloudCoveragePercentage >= 99.0) {
        console.log('A');
    } else {
        console.log('B');
    }
}

async function initEE() {
    try {
        await new Promise((resolve, reject) => {
            ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
        });
        await new Promise((resolve, reject) => {
            ee.initialize(null, null, resolve, reject);
        });
        await runAnalysis();
    } catch (e) {
        console.error('An error occurred during Earth Engine initialization or analysis.');
        console.error(e);
        console.log('D');
    }
}

initEE();
